head.b:skin:
/* CSS RESET ĐẶC TRỊ LỖI KHOẢNG CÁCH BLOGSPOT */
* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { background-color: #0b0f19; color: #f8fafc; font-family: 'Outfit', sans-serif; min-height: 100vh; }

.blogspot-anti-break br { display: none !important; }
.blogspot-anti-break p, .blogspot-anti-break h3, .blogspot-anti-break h4 { margin: 0 !important; padding: 0 !important; }
.blogspot-anti-break span, .blogspot-anti-break div { border: none; }

/* LAYOUT & UTILITIES */
.container { max-width: 1200px; margin: 0 auto; padding: 0 1.2rem; }
.gradient-text-gold { background: linear-gradient(135deg, #fbbf24, #f59e0b); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }

/* HEADER & NAVBAR */
.site-header { position: sticky; top: 0; z-index: 100; background: rgba(11, 15, 25, 0.85); backdrop-filter: blur(16px); border-bottom: 1px solid rgba(255,255,255,0.08); padding: 0.8rem 0; }
.nav-wrap { display: flex; align-items: center; justify-content: space-between; gap: 1rem; }
.brand-logo { display: flex; align-items: center; gap: 0.6rem; text-decoration: none; font-size: 1.4rem; font-weight: 800; color: #fff; }
.cart-btn-trigger { position: relative; background: linear-gradient(135deg, #2563eb, #1d4ed8); border: none; color: #fff; padding: 0.6rem 1.2rem; border-radius: 99px; font-weight: 600; cursor: pointer; display: flex; align-items: center; gap: 0.5rem; }
.cart-badge { background: #ef4444; color: #fff; font-size: 0.75rem; font-weight: 700; width: 20px; height: 20px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; }

/* HERO FEATURED BANNER */
.hero-sec { margin: 1.5rem 0; }
.hero-card { background: linear-gradient(135deg, rgba(30,41,59,0.7), rgba(15,23,42,0.8)); border: 1px solid rgba(255,255,255,0.1); border-radius: 1.2rem; padding: 1.5rem; display: grid; grid-template-columns: 1fr 1.2fr; gap: 1.5rem; align-items: center; }
.hero-img img { width: 100%; max-height: 280px; object-fit: cover; border-radius: 0.8rem; }
.badge-hot { background: rgba(239,68,68,0.2); color: #f87171; border: 1px solid rgba(239,68,68,0.3); padding: 0.3rem 0.8rem; border-radius: 99px; font-size: 0.8rem; font-weight: 700; }

/* CATEGORY CHIPS */
.chip-bar { display: flex; gap: 0.6rem; overflow-x: auto; padding: 0.8rem 0; margin-bottom: 1.5rem; }
.chip-btn { background: rgba(30,41,59,0.8); border: 1px solid rgba(255,255,255,0.1); color: #94a3b8; padding: 0.5rem 1rem; border-radius: 99px; white-space: nowrap; cursor: pointer; transition: all 0.2s; }
.chip-btn.active, .chip-btn:hover { background: #2563eb; color: #fff; border-color: #3b82f6; }

/* PRODUCTS GRID */
.grid-catalog { display: grid; grid-template-columns: repeat(auto-fill, minmax(250px, 1fr)); gap: 1.2rem; margin-bottom: 3rem; }
.product-card { background: rgba(18, 24, 38, 0.9); border: 1px solid rgba(255,255,255,0.08); border-radius: 1rem; overflow: hidden; display: flex; flex-direction: column; transition: transform 0.2s, border-color 0.2s; }
.product-card:hover { transform: translateY(-4px); border-color: rgba(59, 130, 246, 0.4); }
.card-img-wrap { position: relative; width: 100%; aspect-ratio: 4/3; background: #000; overflow: hidden; }
.card-img-wrap img { width: 100%; height: 100%; object-fit: cover; cursor: pointer; }
.badge-cat { position: absolute; top: 8px; left: 8px; background: rgba(0,0,0,0.6); color: #fbbf24; backdrop-filter: blur(4px); font-size: 0.75rem; padding: 0.2rem 0.6rem; border-radius: 6px; }
.card-body { padding: 1rem; display: flex; flex-direction: column; flex: 1; justify-content: space-between; }
.card-title { font-size: 1rem; font-weight: 600; color: #f1f5f9; margin-bottom: 0.5rem; cursor: pointer; }
.price-row { display: flex; align-items: center; justify-content: space-between; margin-bottom: 1rem; }
.price-val { font-size: 1.1rem; font-weight: 700; color: #fbbf24; }
.deposit-tag { font-size: 0.8rem; color: #38bdf8; }
.card-actions { display: flex; gap: 0.5rem; }
.btn-primary { background: linear-gradient(135deg, #f59e0b, #d97706); color: #000; border: none; padding: 0.6rem 1rem; border-radius: 8px; font-weight: 700; cursor: pointer; display: flex; align-items: center; gap: 0.4rem; }
.btn-secondary { background: rgba(255,255,255,0.08); color: #fff; border: 1px solid rgba(255,255,255,0.15); padding: 0.6rem 1rem; border-radius: 8px; font-weight: 600; cursor: pointer; }

/* MODALS & CART DRAWER */
.modal-overlay { position: fixed; inset: 0; background: rgba(0,0,0,0.75); backdrop-filter: blur(8px); z-index: 1000; display: none; align-items: center; justify-content: center; padding: 1rem; }
.modal-overlay.active { display: flex; }
.modal-card { background: #0f172a; border: 1px solid rgba(255,255,255,0.15); border-radius: 1.2rem; width: 100%; max-width: 480px; max-height: 90vh; overflow-y: auto; padding: 1.5rem; position: relative; }
.modal-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 1rem; }
.close-btn { background: none; border: none; color: #94a3b8; font-size: 1.2rem; cursor: pointer; }
.form-control { width: 100%; background: #1e293b; border: 1px solid rgba(255,255,255,0.1); color: #fff; padding: 0.8rem 1rem; border-radius: 8px; font-size: 0.95rem; }

@media (max-width: 768px) {
  .hero-card { grid-template-columns: 1fr; }
}

